MOVES = {"N": (0, -1), "S": (0, 1), "E": (1, 0), "W": (-1, 0)}

def step(snake, direction, grow=False):
    x, y = snake[0]
    dx, dy = MOVES[direction]
    new = [(x + dx, y + dy)] + list(snake)
    if not grow:
        new.pop()
    return new
